add_action( 'woocommerce_checkout_order_processed', 'perfectpixel_update_user_meta_after_order', 20, 3 );

function perfectpixel_update_user_meta_after_order( $order_id, $posted_data, $order ) {
	$user_id = $order instanceof WC_Order ? $order->get_customer_id() : 0;
	if ( ! $user_id ) {
		return; // Guest order.
	}
	update_user_meta( $user_id, 'perfectpixel_last_order_date', current_time( 'mysql' ) );
	update_user_meta( $user_id, 'perfectpixel_last_order_id', $order->get_id() );

	// More examples:
	// update_user_meta( $user_id, 'perfectpixel_bought_course', 'yes' );
	// update_user_meta( $user_id, 'perfectpixel_last_payment_method', $order->get_payment_method() );
}
